begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select ok(not has_function_privilege('anon','api.portal_room_snapshot(text,uuid)','execute'),'anonymous room denied');
select ok(not has_function_privilege('authenticated','api.portal_invitation_mail_payload(uuid)','execute'),'invitation secret material is worker-only');
select ok(not has_function_privilege('authenticated','app_private.poortkamer_invite_token(uuid)','execute'),'token derivation is private');
select ok(not has_table_privilege('authenticated','app_private.portal_team_invites','select'),'invite table is private');
select ok(not has_table_privilege('anon','app_private.portal_room_messages','select'),'chat is never public');
select is((select count(*)::integer from app_private.portal_owners where portal_id='12000000-0000-0000-0000-000000000001' and role='owner' and revoked_at is null),1,'seed owner backfilled');
select set_config('request.jwt.claims','{"sub":"e0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is(api.portal_room_snapshot('duindorp-halloween-2026')->>'role','owner','existing resident is primary');
select ok(api.portal_room_snapshot('duindorp-halloween-2026')->>'portalTopic' like 'portal-room:%','versioned private topic');
select is(jsonb_array_length(api.portal_room_snapshot('duindorp-halloween-2026')->'channels'),7,'four house rooms plus two public rooms and one announcement channel');
select is((select string_agg(channel->>'name','|' order by position) from jsonb_array_elements(api.portal_room_snapshot('duindorp-halloween-2026')->'channels') with ordinality item(channel,position) where channel->>'kind'='team'),'Achter de Poort|Voorbereiding|Decor en techniek|Tijdens de avond','house rooms are private channels in their fixed order');
select is((select string_agg(channel->>'name','|' order by position) from jsonb_array_elements(api.portal_room_snapshot('duindorp-halloween-2026')->'channels') with ordinality item(channel,position) where channel->>'kind'='community'),'Algemeen|Hulp gevraagd','only Algemeen and Hulp gevraagd are public between houses');
select is((select channel->>'name' from jsonb_array_elements(api.portal_room_snapshot('duindorp-halloween-2026')->'channels') with ordinality item(channel,position) where channel->>'kind'='community' order by position limit 1),'Algemeen','Algemeen is the first Praatkamer channel');
select is((select count(*)::integer from app_private.portal_room_channels where portal_id is null and kind='community' and archived_at is null),2,'database has exactly two active event-wide chat rooms');
select ok(not exists(select 1 from app_private.portal_room_channels where portal_id is null and kind='community' and archived_at is null and name in ('Voorbereiding','Decor en techniek','Tijdens de avond')),'house rooms have no active event-wide variants');
select ok((api.portal_room_snapshot('duindorp-halloween-2026')->'visits')::text !~ 'email|phone|street|firstName|lastName','visit projection contains no household PII');
select set_config('test.old_topic',api.portal_room_snapshot('duindorp-halloween-2026')->>'portalTopic',true);
select set_config('test.team_channel',(select id::text from app_private.portal_room_channels where portal_id='12000000-0000-0000-0000-000000000001' and name='Achter de Poort' and archived_at is null),true);
select set_config('test.community_channel',(select id::text from app_private.portal_room_channels where kind='community' and name='Hulp gevraagd' and archived_at is null limit 1),true);
select set_config('test.announcements',(select id::text from app_private.portal_room_channels where kind='announcements' and archived_at is null limit 1),true);
select set_config('test.archived_channel',(select id::text from app_private.portal_room_channels where portal_id is null and name='Decor en techniek' and archived_at is not null limit 1),true);
select app_private.poortkamer_channels((select event_id from app_private.portals where id='12000000-0000-0000-0000-000000000002'),'12000000-0000-0000-0000-000000000002');
select set_config('test.foreign_team_channel',(select id::text from app_private.portal_room_channels where portal_id='12000000-0000-0000-0000-000000000002' and name='Voorbereiding' and archived_at is null),true);
select throws_ok($$select api.portal_chat_snapshot(current_setting('test.archived_channel')::uuid)$$,'42501','NOT_AUTHORIZED','archived shared preparation rooms cannot be opened by known id');
select lives_ok($$select api.portal_team_command('12000000-0000-0000-0000-000000000001','invite','{"email":"parent-a@example.invalid","firstName":"Mila","lastName":"Geheim","role":"viewer"}','94000000-0000-0000-0000-000000000001')$$,'owner shares a viewer key');
select set_config('test.invite_id',(select id::text from app_private.portal_team_invites where email='parent-a@example.invalid'),true);
select set_config('test.token',app_private.poortkamer_invite_token(current_setting('test.invite_id')::uuid),true);
select is(octet_length((select token_hash from app_private.portal_team_invites where id=current_setting('test.invite_id')::uuid)),32,'only sha256 token digest persisted');
select ok((select payload::text not like '%'||current_setting('test.token')||'%' from app_private.email_outbox where dedupe_key='portal-invite:'||current_setting('test.invite_id')),'raw token never in durable outbox');
select lives_ok($$select api.portal_team_command('12000000-0000-0000-0000-000000000001','invite','{"email":"parent-a@example.invalid","firstName":"Mila","lastName":"Geheim","role":"viewer"}','94000000-0000-0000-0000-000000000001')$$,'idempotent invitation retry');
select is((select count(*)::integer from app_private.portal_team_invites where email='parent-a@example.invalid'),1,'one invitation after retry');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select throws_ok($$select api.portal_invitation_accept(current_setting('test.token'))$$,'42501','INVITATION_UNAVAILABLE','another verified email cannot accept');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$select api.portal_invitation_accept(current_setting('test.token'))$$,'exact verified email accepts');
select throws_ok($$select api.portal_invitation_accept(current_setting('test.token'))$$,'42501','INVITATION_UNAVAILABLE','invitation is single use');
select is(api.portal_room_snapshot('duindorp-halloween-2026')->>'role','viewer','accepted viewer gets room');
select throws_ok($$select api.portal_chat_snapshot(current_setting('test.foreign_team_channel')::uuid)$$,'42501','NOT_AUTHORIZED','a house cannot open another house preparation room');
select ok(not app_private.can_access_realtime_topic(current_setting('test.old_topic')),'old topic invalidated after membership change');
select ok(app_private.can_access_realtime_topic(api.portal_room_snapshot('duindorp-halloween-2026')->>'portalTopic'),'new topic authorized');
select throws_ok($$select api.portal_room_update('12000000-0000-0000-0000-000000000001','stock','{"stock":"low"}',gen_random_uuid())$$,'42501','NOT_AUTHORIZED','viewer cannot change stock');
select throws_ok($$select api.portal_set_operational_state('12000000-0000-0000-0000-000000000001','open',1,'Test operation')$$,'42501','NOT_AUTHORIZED','legacy state API also denies viewer');
select throws_ok($$select api.portal_rotate_credential('12000000-0000-0000-0000-000000000001',1,'Replace test QR')$$,'42501','NOT_AUTHORIZED','legacy credential API denies viewer');
select throws_ok($$select api.portal_team_command('12000000-0000-0000-0000-000000000001','invite','{}',gen_random_uuid())$$,'42501','NOT_AUTHORIZED','viewer cannot invite');
select lives_ok($$select api.portal_chat_send(current_setting('test.team_channel')::uuid,'Wij zijn er klaar voor','94000000-0000-0000-0000-000000000002','12000000-0000-0000-0000-000000000001')$$,'viewer can chat internally');
select lives_ok($$select api.portal_chat_send(current_setting('test.team_channel')::uuid,'Wij zijn er klaar voor','94000000-0000-0000-0000-000000000002','12000000-0000-0000-0000-000000000001')$$,'chat retry is idempotent');
select is((select count(*)::integer from app_private.portal_room_messages where body='Wij zijn er klaar voor'),1,'one chat message after retry');
select lives_ok($$select api.portal_chat_send(current_setting('test.community_channel')::uuid,'Welkom op het plein',gen_random_uuid(),'12000000-0000-0000-0000-000000000001')$$,'viewer can use community');
select ok(api.portal_chat_snapshot(current_setting('test.community_channel')::uuid)::text not like '%Geheim%','community does not expose surname');
select ok(api.portal_chat_snapshot(current_setting('test.team_channel')::uuid)::text like '%Mila Geheim%','own team sees full name');
select throws_ok($$select api.portal_chat_send(current_setting('test.announcements')::uuid,'Onbevoegde omroep',gen_random_uuid(),'12000000-0000-0000-0000-000000000001')$$,'42501','NOT_AUTHORIZED','resident cannot publish announcement');
select throws_ok($$select api.portal_room_snapshot('duindorp-halloween-2026','12000000-0000-0000-0000-000000000002')$$,'42501','NOT_AUTHORIZED','no access to another portal');
select set_config('request.jwt.claims','{"sub":"e0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$select api.portal_team_command('12000000-0000-0000-0000-000000000001','role','{"userId":"a0000000-0000-0000-0000-000000000001","role":"crew"}',gen_random_uuid())$$,'owner can promote crew');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$select api.portal_room_update('12000000-0000-0000-0000-000000000001','stock','{"stock":"low"}',gen_random_uuid())$$,'crew can update stock');
select lives_ok($$select api.portal_room_update('12000000-0000-0000-0000-000000000001','checklist','{"item":"phone","done":true}',gen_random_uuid())$$,'crew can prepare');
select throws_ok($$select api.portal_room_update('12000000-0000-0000-0000-000000000001','details','{}',gen_random_uuid())$$,'42501','NOT_AUTHORIZED','crew cannot edit permanent details');
select throws_ok($$select api.portal_team_command('12000000-0000-0000-0000-000000000001','revoke','{}',gen_random_uuid())$$,'42501','NOT_AUTHORIZED','crew cannot administer access');
select lives_ok($$select api.portal_room_update('12000000-0000-0000-0000-000000000001','status',jsonb_build_object('state','paused','minutes',5,'version',(api.portal_room_snapshot('duindorp-halloween-2026')#>>'{portal,version}')::integer,'reason','Even op adem komen'),'94000000-0000-0000-0000-000000000003')$$,'crew can schedule pause');
select is((select extract(epoch from pause_until-now())::integer from app_private.portals where id='12000000-0000-0000-0000-000000000001'),300,'pause duration stored durably');
update app_private.portals set pause_until=now()-interval '1 second' where id='12000000-0000-0000-0000-000000000001';
select lives_ok($$select app_private.poortkamer_tick()$$,'durable timer runs without a client');
select is((select operation_status::text from app_private.portals where id='12000000-0000-0000-0000-000000000001'),'open','due pause resumes');
select lives_ok($$select api.portal_room_update('12000000-0000-0000-0000-000000000001','status',jsonb_build_object('state','closed','version',(api.portal_room_snapshot('duindorp-halloween-2026')#>>'{portal,version}')::integer,'reason','Ontvangst gestopt'),gen_random_uuid())$$,'manual stop is accepted');
select app_private.poortkamer_tick();
select is((select operation_status::text from app_private.portals where id='12000000-0000-0000-0000-000000000001'),'closed','timer never reopens manually stopped portal');
select set_config('request.jwt.claims','{"sub":"e0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$select api.portal_team_command('12000000-0000-0000-0000-000000000001','role','{"userId":"a0000000-0000-0000-0000-000000000001","role":"coadmin"}',gen_random_uuid())$$,'coadmin promotion');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$select api.portal_room_update('12000000-0000-0000-0000-000000000001','details',jsonb_build_object('name','De Testpoort','description','Besloten omschrijving','version',(api.portal_room_snapshot('duindorp-halloween-2026')#>>'{portal,version}')::integer),gen_random_uuid())$$,'coadmin can edit permanent name');
select throws_ok($$select api.portal_team_command('12000000-0000-0000-0000-000000000001','transfer','{}',gen_random_uuid())$$,'42501','NOT_AUTHORIZED','coadmin cannot transfer ownership');
select set_config('test.revoked_topic',api.portal_room_snapshot('duindorp-halloween-2026')->>'portalTopic',true);
select set_config('request.jwt.claims','{"sub":"e0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$select api.portal_team_command('12000000-0000-0000-0000-000000000001','revoke','{"userId":"a0000000-0000-0000-0000-000000000001"}',gen_random_uuid())$$,'owner revokes access');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($$select api.portal_room_snapshot('duindorp-halloween-2026','12000000-0000-0000-0000-000000000001')$$,'42501','NOT_AUTHORIZED','revoked member cannot read room');
select throws_ok($$select api.portal_chat_snapshot(current_setting('test.team_channel')::uuid)$$,'42501','NOT_AUTHORIZED','revoked member cannot read history');
select ok(not app_private.can_access_realtime_topic(current_setting('test.revoked_topic')),'revoked topic no longer authorized');
select ok(not app_private.poortkamer_community((select id from app_private.events limit 1)),'revoked last membership loses community');
select set_config('request.jwt.claims','{"sub":"f0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$select api.portal_chat_send(current_setting('test.announcements')::uuid,'Belangrijke mededeling',gen_random_uuid(),null,'{}',true)$$,'admin can publish urgent announcement');
select ok(exists(select 1 from app_private.portal_push_outbox where kind='urgent'),'urgent push queued');
select is((select p->>'stock' from jsonb_array_elements(api.admin_portal_room_snapshot('duindorp-halloween-2026')->'portals') p where p->>'id'='12000000-0000-0000-0000-000000000001'),'low','low stock appears in organizer view');
select lives_ok($$select api.portal_chat_action(current_setting('test.community_channel')::uuid,'hide',jsonb_build_object('messageId',(select id from app_private.portal_room_messages where body='Welkom op het plein')))$$,'admin can hide community message');
select ok(api.portal_chat_snapshot(current_setting('test.community_channel')::uuid)::text not like '%Welkom op het plein%','hidden body is not returned');
select ok(exists(select 1 from app_private.audit_events where action='portal.chat.hide'),'moderation audited');
select set_config('request.jwt.claims','{"sub":"e0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
insert into app_private.portal_owners(portal_id,user_id,role) values('12000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000002','coadmin');
select lives_ok($$select api.portal_team_command('12000000-0000-0000-0000-000000000001','transfer','{"userId":"a0000000-0000-0000-0000-000000000002"}',gen_random_uuid())$$,'owner transfer reuses memberships');
select is((select count(*)::integer from app_private.portal_owners where portal_id='12000000-0000-0000-0000-000000000001' and role='owner' and revoked_at is null),1,'exactly one primary after transfer');
select lives_ok($$set constraints app_private.portal_primary_membership,app_private.portal_primary_required immediate$$,'deferred ownership invariant holds');
select lives_ok($$select api.portal_notification_preferences_set('{"mention":false}')$$,'notification preferences are per-user');
select is((select mention from app_private.portal_notification_preferences where user_id='e0000000-0000-0000-0000-000000000001'),false,'mention preference stored');
select app_private.poortkamer_push('12000000-0000-0000-0000-000000000001','mention','test-dedupe');
select app_private.poortkamer_push('12000000-0000-0000-0000-000000000001','mention','test-dedupe');
select is((select count(*)::integer from app_private.portal_push_outbox where dedupe_key='test-dedupe'),2,'one notification per active member despite duplicate enqueue');
update app_private.events set local_date=(now()-interval '2 months')::date;
select app_private.poortkamer_tick();
select is((select count(*)::integer from app_private.portal_room_messages),0,'one-month retention erases chat');
select ok(exists(select 1 from app_private.portal_owners),'retention preserves memberships');
select ok(exists(select 1 from app_private.audit_events where action='portal.chat.sent'),'retention preserves audit');
select * from finish();
rollback;
